import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Path traversal / Directory traversal","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/web/path-traversal.md","filePath":"d/web/path-traversal.md","lastUpdated":1781102819000}`),a={name:`d/web/path-traversal.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/web/path-traversal.md for this page in Markdown format</div><h1 id="path-traversal-directory-traversal" tabindex="-1">Path traversal / Directory traversal <a class="header-anchor" href="#path-traversal-directory-traversal" aria-label="Permalink to “Path traversal / Directory traversal”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Path Traversal is a web security vulnerability that allows an attacker to access files and directories on the underlying web server of a web application. Access to files and directories in a path traversal attack is restricted solely by the existing access controls of the underlying operating system. Web servers usually limit access to a specific part of the file system: the &quot;web root&quot;. This directory contains all files required for the functionality of the web application. Attackers use special strings in path specifications to break out of the web root folder using a path traversal attack.</p><p>In the simplest form, an attacker uses the string &quot;../&quot; to change the location of the resource requested in the parameter. This string is a relative path specification. It refers specifically to the parent directory of the current working directory. Attackers also often use alternative encodings of the &quot;../&quot; sequence to bypass any security filters that may be in place. These methods include valid and invalid Unicode-encoded (&quot;..%u2216&quot; or &quot;..%c0%af&quot;), URL-encoded (&quot;%2e%2e%2f&quot;), and duplicate URL-encoded characters (&quot;..%255c&quot;) of the backslash character. Advanced techniques also often use additional special characters such as the period &quot;.&quot; to refer to the current working directory or the &quot;%00&quot; NULL character to bypass rudimentary end-of-file checks.</p><p>In a successful attack, an attacker can use path traversal to access arbitrary files and directories on the vulnerable system. This may include sensitive operating system files, application code, or configuration files. Path Traversal may also provide write access to files and directories, sometimes allowing attackers to gain code execution and, thus, complete control over the web server.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><ul><li>Avoid using custom filenames and path specifications in the web application and use indexes instead (e.g., index: 5 corresponds to &quot;images/img.png&quot;).</li><li>Ensure that only valid and expected client input is accepted. Discard all other inputs.</li><li>If you have to normalize paths, consider that characters may be single or multiple encoded (such as URL encoded, e.g., <code>%20</code> or <code>%2520</code> instead of a space).</li></ul>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};